#include "thinkercad/moduledevices.hpp"
#include "thinkercad/electronics.hpp"
#include "thinkercad/uartbus.hpp"
#include <algorithm>
#include <cmath>
#include <iostream>
#include <stdexcept>
using namespace thinkercad;
void check(bool condition,const char* message){if(!condition)throw std::runtime_error(message);}
struct Radios {
    CircuitDocument doc;ModuleDevices devices;std::string a,b;
    Radios(std::string model){a=doc.addPart(PartKind::Module,0,0);b=doc.addPart(PartKind::Module,300,0);for(auto id:{a,b}){doc.part(id).model=model;doc.connect({"board","3V3"},{id,"VCC"});doc.connect({"board","GND"},{id,"GND"});}sync();}
    void sync(){Esp8266Board board;devices.synchronizePower(doc,doc.solve(board));}
    std::uint8_t transaction(std::string id,std::vector<std::uint8_t> bytes){auto& part=doc.part(id);devices.select(part,true);std::uint8_t out=0;for(auto byte:bytes)out=devices.spi(part,byte,0);devices.select(part,false);return out;}
    void write(std::string id,int at,int value){transaction(id,{std::uint8_t(at|(doc.part(id).model=="sx1276"?0x80:0)),std::uint8_t(value)});}
    unsigned read(std::string id,int at){return transaction(id,{std::uint8_t(at|(doc.part(id).model=="cc1101"?0xc0:0)),0});}
};
struct Serial {
    CircuitDocument doc;Esp8266Board board;UartBus uart;std::string id;
    Serial(std::string model,unsigned baud,double supply){doc.part("board").model="esp32";board.configure("esp32");board.pinMode(17,PinMode::Output);board.digitalWrite(17,true);board.pinMode(16,PinMode::Input);id=doc.addPart(PartKind::Module,0,0);doc.part(id).model=model;auto power=doc.addPart(PartKind::PowerSupply,0,0);doc.part(power).value=supply;doc.connect({power,"+"},{id,"VCC"});doc.connect({power,"-"},{id,"GND"});doc.connect({"board","GND"},{id,"GND"});doc.connect({"board","GPIO17"},{id,"RX"});doc.connect({id,"TX"},{"board","GPIO16"});UartBus::Config c;c.baud=baud;c.rx=16;c.tx=17;uart.begin(doc,"board",1,c);}
    std::vector<std::uint8_t> send(std::vector<std::uint8_t> bytes){uart.write(doc,doc.solve(board),"board",1,bytes,0,true,{{"board",&board}});std::vector<std::uint8_t> out;while(uart.available("board",1,10000000))out.push_back(std::uint8_t(uart.read("board",1,10000000)));return out;}
    std::string command(std::string value){auto out=send({value.begin(),value.end()});return {out.begin(),out.end()};}
};
int main(){
    {Radios f("cc1101");check(f.read(f.a,0x31)==0x14,"CC1101 VERSION");f.transaction(f.b,{0x34});f.transaction(f.a,{0x7f,3,'a','b','c'});f.transaction(f.a,{0x35});check((f.read(f.b,0x3b)&127)==6,"CC1101 variable length packet and appended status");check(f.read(f.b,0x3f)==3&&f.read(f.b,0x3f)=='a',"CC1101 FIFO is not an incrementing register bank");f.transaction(f.b,{0x3a});f.write(f.b,0x0a,7);f.transaction(f.b,{0x34});f.transaction(f.a,{0x7f,1,42});f.transaction(f.a,{0x35});check(f.read(f.b,0x3b)==0,"channel mismatch prevents delivery");f.write(f.b,0x0a,0);f.transaction(f.b,{0x34});f.doc.removePart(f.a);f.sync();check(f.read(f.b,0x3b)==0,"deletion clears powered-radio snapshots");}
    {Radios f("sx1276");check(f.read(f.a,0x42)==0x12,"SX1276 version");f.write(f.b,1,0x85);f.write(f.a,0x0d,0);f.transaction(f.a,{0x80,'h','i'});f.write(f.a,0x22,2);f.write(f.a,1,0x83);check(f.read(f.a,0x12)&8,"LoRa TxDone");check((f.read(f.b,0x12)&0x40)&&f.read(f.b,0x13)==2,"LoRa RxDone and payload length");f.write(f.b,0x0d,f.read(f.b,0x10));check(f.read(f.b,0)=='h'&&f.read(f.b,0)=='i',"LoRa FIFO read pointer");f.write(f.b,0x12,0xff);check(f.read(f.b,0x12)==0,"IRQ flags are write-one-to-clear");f.write(f.b,0x39,0x34);f.write(f.a,1,0x83);check(f.read(f.b,0x12)==0,"LoRa sync word isolates networks");f.write(f.b,0x39,0x12);auto wire=f.doc.wires().front().id;f.doc.removeWire(wire);f.sync();f.write(f.a,1,0x83);check(f.read(f.b,0x12)==0,"unpowered transmitter cannot deliver packets");}
    {ModuleDevices bus;CircuitPart part;part.id="can";part.kind=PartKind::Module;part.model="mcp2515";auto spi=[&](std::vector<std::uint8_t> bytes){bus.select(part,true);std::uint8_t out=0;for(auto b:bytes)out=bus.spi(part,b,0);bus.select(part,false);return out;};check(spi({3,0x0e,0})==0x80,"CAN resets in configuration mode");spi({5,0x0f,0xe0,0x40});check(spi({3,0x0e,0})==0x40,"MCP2515 BIT MODIFY selects loopback mode");spi({0x40,0x24,0x60,0,0,2,'O','K'});spi({0x81});check(spi({3,0x2c,0})&1,"MCP2515 loopback sets RX0IF");check(spi({3,0x65,0})==2&&spi({3,0x66,0})=='O'&&spi({3,0x67,0})=='K',"CAN loopback preserves DLC and payload");spi({0xc0});check(spi({3,0x2c,0})==0,"CAN reset clears pending frames");}
    {Serial f("sim7600",115200,5);check(f.command("AT\r").find("OK")!=std::string::npos,"powered modem answers AT");f.command("ATE0\r");check(f.command("AT+CSQ\r").find("+CSQ: 20,0")!=std::string::npos,"synthetic signal state");f.doc.part(f.id).parameters["sms"]=1;check(f.command("AT+CMGL=\"ALL\"\r").find("synthetic SMS")!=std::string::npos,"synthetic SMS inbox");check(f.command("AT+UNKNOWN\r").find("ERROR")!=std::string::npos,"unsupported modem command is explicit");}
    {Serial f("sim800l",9600,4);check(f.command("AT\r").empty(),"bare GSM module rejects overvoltage on RX");auto wire=std::find_if(f.doc.wires().begin(),f.doc.wires().end(),[&](const auto& w){return w.a==Endpoint{"board","GPIO17"}&&w.b==Endpoint{f.id,"RX"};});check(wire!=f.doc.wires().end(),"UART wire exists");f.doc.removeWire(wire->id);auto top=f.doc.addPart(PartKind::Resistor,0,0),bottom=f.doc.addPart(PartKind::Resistor,0,0);f.doc.part(top).value=1000;f.doc.part(bottom).value=5600;f.doc.connect({"board","GPIO17"},{top,"1"});f.doc.connect({top,"2"},{f.id,"RX"});f.doc.connect({bottom,"1"},{f.id,"RX"});f.doc.connect({bottom,"2"},{f.id,"GND"});check(f.command("AT\r").find("OK")!=std::string::npos,"resistor divider translates GPIO to GSM logic");}
    {Serial f("neo-6m",9600,3.3);check(f.command("$PUBX,00*33\r\n").find("$GPRMC,")!=std::string::npos,"GNSS poll produces NMEA sentences");check(f.command("$PUBX,00*00\r\n").empty(),"GNSS rejects invalid NMEA checksum");f.doc.part(f.id).parameters["fix"]=0;check(f.command("$PUBX,00*33\r\n").find(",V,")!=std::string::npos,"GNSS reports invalid fix");}
    {Serial f("fingerprint-uart",57600,5);auto packet=std::vector<std::uint8_t>{0xef,1,255,255,255,255,1,0,3,1,0,5};auto absent=f.send(packet);check(absent.size()==12&&absent[9]==2,"fingerprint image requires synthetic finger");f.doc.part(f.id).parameters["finger"]=1;auto present=f.send(packet);check(present.size()==12&&present[9]==0,"fingerprint GetImage success");packet.back()=0;auto corrupt=f.send(packet);check(corrupt.size()==12&&corrupt[9]==1,"fingerprint checksum error response");}
    {CircuitPart p;p.kind=PartKind::Module;p.model="li-ion-18650";p.parameters["soc"]=100;auto full=electronicBranches(p,[](auto){return std::optional<double>{};},nullptr,0);p.parameters["soc"]=0;auto empty=electronicBranches(p,[](auto){return std::optional<double>{};},nullptr,0);check(std::abs(full[0].offset-4.2)<1e-9&&empty[0].offset==3,"lithium SOC endpoints");p.model="usb-c-charging";auto cc=electronicBranches(p,[](auto){return std::optional<double>{};},nullptr,0);check(cc.size()==2&&cc[0].resistance==5100&&cc[1].resistance==5100,"USB-C has separate Rd resistors and no fake power source");}
    {CircuitDocument doc;Esp8266Board board;auto cell=doc.addPart(PartKind::Module,0,0);doc.part(cell).model="lipo-1s";doc.part(cell).parameters["soc"]=50;auto charger=doc.addPart(PartKind::Module,0,0);doc.part(charger).model="tp4056";auto source=doc.addPart(PartKind::PowerSupply,0,0);doc.part(source).value=5;doc.connect({cell,"-"},{"board","GND"});doc.connect({source,"-"},{"board","GND"});doc.connect({source,"+"},{charger,"VCC"});doc.connect({charger,"GND"},{"board","GND"});doc.connect({charger,"BAT-"},{cell,"-"});doc.connect({charger,"BAT+"},{cell,"+"});auto state=doc.solve(board);check(state.errors.empty(),"charger DC circuit converges");auto volts=state.voltage.at({cell,"+"});check(volts&&*volts>3.7&&*volts<4.2,"charger raises terminal voltage without exceeding lithium limit");check(std::abs((*volts-3.7)/.08-.5)<.01,"DC charger respects current setting");}
    {CircuitDocument doc;Esp8266Board board;auto can=doc.addPart(PartKind::Module,0,0);doc.part(can).model="tja1050";auto source=doc.addPart(PartKind::PowerSupply,0,0);doc.part(source).value=5;doc.connect({source,"-"},{"board","GND"});doc.connect({source,"+"},{can,"VCC"});doc.connect({can,"GND"},{"board","GND"});doc.connect({can,"TXD"},{"board","GND"});doc.connect({can,"S"},{"board","GND"});auto termination=doc.addPart(PartKind::Resistor,0,0);doc.part(termination).value=120;doc.connect({termination,"1"},{can,"CANH"});doc.connect({termination,"2"},{can,"CANL"});auto state=doc.solve(board);check(state.errors.empty(),"CAN transceiver electrical solve");check(*state.voltage.at({can,"CANH"})-*state.voltage.at({can,"CANL"})>.9&&*state.voltage.at({can,"RXD"})<.1,"dominant bus drives differential output and RXD low");}
    std::cout<<"Radio isolation, CAN loopback, UART device protocols and rechargeable power models passed\n";
}
